import random
from itertools import combinations

def check_girth_6(adj, n):
    # BFS from each vertex, check no cycle of length < 6
    for s in range(n):
        dist = [-1]*n
        parent = [-1]*n
        dist[s] = 0
        queue = [s]
        while queue:
            nxt = []
            for u in queue:
                for v in adj[u]:
                    if dist[v] == -1:
                        dist[v] = dist[u]+1
                        parent[v] = u
                        if dist[v] < 3:
                            nxt.append(v)
                    elif dist[v] == dist[u] and v != parent[u]:
                        # odd cycle of length 2*dist[u]+1
                        if 2*dist[u]+1 < 6:
                            return False
                    elif dist[v] == dist[u]+1 and parent[v] != u:
                        # even cycle of length 2*dist[u]+2
                        if 2*dist[u]+2 < 6:
                            return False
            queue = nxt
    return True

def try_build(seed):
    random.seed(seed)
    n = 24
    max_d = 7
    min_d = 4
    adj = [set() for _ in range(n)]
    edges = []
    pairs = list(combinations(range(n), 2))
    random.shuffle(pairs)

    def adds_short_cycle(u, v):
        # BFS from u avoiding edge (u,v); if v reachable in <5 steps, adding creates cycle <6
        if v in adj[u]:
            return True
        dist = {u: 0}
        queue = [u]
        for _ in range(4):  # depth up to 4
            nxt = []
            for x in queue:
                for y in adj[x]:
                    if y not in dist:
                        dist[y] = dist[x]+1
                        nxt.append(y)
            queue = nxt
            if v in dist:
                return True
        return False

    for u, v in pairs:
        if len(adj[u]) >= max_d or len(adj[v]) >= max_d:
            continue
        if adds_short_cycle(u, v):
            continue
        adj[u].add(v)
        adj[v].add(u)
        edges.append((u,v))

    degs = [len(adj[i]) for i in range(n)]
    if min(degs) >= min_d and max(degs) <= max_d:
        return edges, degs
    return None

for seed in range(200):
    res = try_build(seed)
    if res:
        edges, degs = res
        print("Found at seed", seed, "degs:", degs)
        print("edges:", edges)
        break
else:
    print("not found")

