for i in range(n):
    for j in range(i+1,n):
        E[(i,j)] = Bool(f'e_{i}_{j}')

def edge(i,j):
    if i==j: return BoolVal(False)
    if i>j: i,j=j,i
    return E[(i,j)]

from itertools import combinations, permutations

for i in range(n):
    degv = Sum([If(edge(i,j),1,0) for j in range(n) if j!=i])
    s.add(degv >= 4, degv <= 7)

for i,j,k in combinations(range(n),3):
    s.add(Not(And(edge(i,j), edge(j,k), edge(i,k))))

for i,j in combinations(range(n),2):
    cn = Sum([If(And(edge(i,k),edge(j,k)),1,0) for k in range(n) if k!=i and k!=j])
    s.add(cn <= 1)

count = 0
