        cyc = (a,) + perm
        rev = (cyc[0],) + cyc[:0:-1]
        key = min(cyc, rev)
        if key in seen: continue
        seen.add(key)
        constraints = [edge(cyc[i], cyc[(i+1)%5]) for i in range(5)]
