    for u,v in edges: adj[u].add(v); adj[v].add(u)
    degs = [len(adj[i]) for i in range(n)]
    print("degs", degs)
    girth = float('inf')
    for st in range(n):
        dist=[-1]*n; parent=[-1]*n; dist[st]=0; q=[st]
        while q:
            nxt=[]
            for u in q:
                for w in adj[u]:
                    if dist[w]==-1:
                        dist[w]=dist[u]+1; parent[w]=u; nxt.append(w)
                    elif parent[u]!=w:
                        c=dist[u]+dist[w]+1
                        if c<girth: girth=c
            q=nxt
