from itertools import combinations, permutations
import time

n = 24
vpool = IDPool()
def E(i,j):
    if i>j: i,j=j,i
    return vpool.id(('e',i,j))

for i,j in combinations(range(n),2):
    E(i,j)

solver = Glucose4()

for i in range(n):
    lits = [E(i,j) for j in range(n) if j!=i]
    cnf1 = CardEnc.atleast(lits=lits, bound=4, vpool=vpool, encoding=EncType.seqcounter)
    for c in cnf1.clauses: solver.add_clause(c)
    cnf2 = CardEnc.atmost(lits=lits, bound=7, vpool=vpool, encoding=EncType.seqcounter)
    for c in cnf2.clauses: solver.add_clause(c)

for i,j,k in combinations(range(n),3):
    solver.add_clause([-E(i,j), -E(j,k), -E(i,k)])

for i,j in combinations(range(n),2):
    others = [k for k in range(n) if k!=i and k!=j]
    for k1,k2 in combinations(others,2):
        solver.add_clause([-E(i,k1),-E(j,k1),-E(i,k2),-E(j,k2)])

for sub in combinations(range(n),5):
